import { Injectable } from '@angular/core';
import { BaseStyle } from 'primeng/base';

const classes = {
    root: 'p-inputpassword p-component'
};

@Injectable()
export class InputPasswordStyle extends BaseStyle {
    name = 'inputpassword';

    classes = classes;
}

/**
 *
 * InputPassword is an extension to standard input element with mask toggling.
 *
 * [Live Demo](https://www.primeng.org/inputpassword/)
 *
 * @module inputpasswordstyle
 *
 */
export enum InputPasswordClasses {
    /**
     * The class of root element
     */
    root = 'p-inputpassword'
}
