import { Directive, inject, model, NgModule } from '@angular/core';
import { PARENT_INSTANCE } from 'primeng/basecomponent';
import { BaseComponent } from 'primeng/basecomponent';
import { InputText } from 'primeng/inputtext';
import { InputPasswordPassThrough } from 'primeng/types/inputpassword';
import { InputPasswordStyle } from './style/inputpasswordstyle';

/**
 * InputPassword directive is an extension to standard input element with mask toggling.
 * @group Components
 */
@Directive({
    selector: '[pInputPassword]',
    standalone: true,
    host: {
        '[attr.type]': 'inputType',
        '[class]': "cx('root')"
    },
    providers: [InputPasswordStyle, { provide: PARENT_INSTANCE, useExisting: InputPassword }],
    hostDirectives: [
        {
            directive: InputText,
            inputs: ['invalid', 'variant', 'fluid', 'pSize', 'pInputTextPT', 'pInputTextUnstyled', 'hostName']
        }
    ]
})
export class InputPassword extends BaseComponent<InputPasswordPassThrough> {
    componentName = 'InputPassword';

    /**
     * Whether the password is masked.
     * @defaultValue true
     * @group Props
     */
    mask = model<boolean>(true);

    _componentStyle = inject(InputPasswordStyle);

    /**
     * Toggles the mask state between password and text.
     * @group Methods
     */
    toggleMask() {
        this.mask.set(!this.mask());
    }

    get inputType(): string {
        return this.mask() ? 'password' : 'text';
    }
}

@NgModule({
    imports: [InputPassword],
    exports: [InputPassword]
})
export class InputPasswordModule {}
